pub const Format = enum {
    DJUk8,
    DJUk6,
    JK,
    JUd5Sk12,
    Ud15,
    DJKUa2,
    DJK,
    DJ,
    EMPTY,
    DJUk5Um5,
    JUd5,
    JSd5Sk16,
    DSj20,
    DJUk14,
    DJSk16,
    DJKUa3,
    DJUk5,
    DJSk14,
    JKUd5,
    DJUk12,
    DUj5,
    DJUk6Um6,
    DJSk12,
    Sd10Sk16,
    JUk8,
    DJKA,
};

pub const Data = union(Format) {
    DJUk8: struct { rd: Register, rj: Register, imm0: u8 },
    DJUk6: struct { rd: Register, rj: Register, imm0: u6 },
    JK: struct { rj: Register, rk: Register },
    JUd5Sk12: struct { rj: Register, imm0: u5, imm1: i12 },
    Ud15: struct { imm0: u15 },
    DJKUa2: struct { rd: Register, rj: Register, rk: Register, imm0: u2 },
    DJK: struct { rd: Register, rj: Register, rk: Register },
    DJ: struct { rd: Register, rj: Register },
    EMPTY,
    DJUk5Um5: struct { rd: Register, rj: Register, imm0: u5, imm1: u5 },
    JUd5: struct { rj: Register, imm0: u5 },
    JSd5Sk16: struct { rj: Register, imm0: i5, imm1: i16 },
    DSj20: struct { rd: Register, imm0: i20 },
    DJUk14: struct { rd: Register, rj: Register, imm0: u14 },
    DJSk16: struct { rd: Register, rj: Register, imm0: i16 },
    DJKUa3: struct { rd: Register, rj: Register, rk: Register, imm0: u3 },
    DJUk5: struct { rd: Register, rj: Register, imm0: u5 },
    DJSk14: struct { rd: Register, rj: Register, imm0: i14 },
    JKUd5: struct { rj: Register, rk: Register, imm0: u5 },
    DJUk12: struct { rd: Register, rj: Register, imm0: u12 },
    DUj5: struct { rd: Register, imm0: u5 },
    DJUk6Um6: struct { rd: Register, rj: Register, imm0: u6, imm1: u6 },
    DJSk12: struct { rd: Register, rj: Register, imm0: i12 },
    Sd10Sk16: struct { imm0: i10, imm1: i16 },
    JUk8: struct { rj: Register, imm0: u8 },
    DJKA: struct { rd: Register, rj: Register, rk: Register, ra: Register },

    pub fn enc(self: Data) u32 {
        return switch (self) {
            .DJUk8 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u8, @bitCast(data.imm0))) << 10),
            .DJUk6 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u6, @bitCast(data.imm0))) << 10),
            .JK => |data| (@as(u32, data.rj.enc()) << 5) | (@as(u32, data.rk.enc()) << 10),
            .JUd5Sk12 => |data| (@as(u32, data.rj.enc()) << 5) | @as(u32, @intCast(@as(u5, @bitCast(data.imm0)))) | (@as(u32, @as(u12, @bitCast(data.imm1))) << 10),
            .Ud15 => |data| @as(u32, @intCast(@as(u15, @bitCast(data.imm0)))),
            .DJKUa2 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, data.rk.enc()) << 10) | (@as(u32, @as(u2, @bitCast(data.imm0))) << 15),
            .DJK => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, data.rk.enc()) << 10),
            .DJ => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5),
            .EMPTY => 0,
            .DJUk5Um5 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u5, @bitCast(data.imm0))) << 10) | (@as(u32, @as(u5, @bitCast(data.imm1))) << 16),
            .JUd5 => |data| (@as(u32, data.rj.enc()) << 5) | @as(u32, @intCast(@as(u5, @bitCast(data.imm0)))),
            .JSd5Sk16 => |data| (@as(u32, data.rj.enc()) << 5) | @as(u32, @intCast(@as(u5, @bitCast(data.imm0)))) | (@as(u32, @as(u16, @bitCast(data.imm1))) << 10),
            .DSj20 => |data| data.rd.enc() | (@as(u32, @as(u20, @bitCast(data.imm0))) << 5),
            .DJUk14 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u14, @bitCast(data.imm0))) << 10),
            .DJSk16 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u16, @bitCast(data.imm0))) << 10),
            .DJKUa3 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, data.rk.enc()) << 10) | (@as(u32, @as(u3, @bitCast(data.imm0))) << 15),
            .DJUk5 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u5, @bitCast(data.imm0))) << 10),
            .DJSk14 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u14, @bitCast(data.imm0))) << 10),
            .JKUd5 => |data| (@as(u32, data.rj.enc()) << 5) | (@as(u32, data.rk.enc()) << 10) | @as(u32, @intCast(@as(u5, @bitCast(data.imm0)))),
            .DJUk12 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u12, @bitCast(data.imm0))) << 10),
            .DUj5 => |data| data.rd.enc() | (@as(u32, @as(u5, @bitCast(data.imm0))) << 5),
            .DJUk6Um6 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u6, @bitCast(data.imm0))) << 10) | (@as(u32, @as(u6, @bitCast(data.imm1))) << 16),
            .DJSk12 => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u12, @bitCast(data.imm0))) << 10),
            .Sd10Sk16 => |data| @as(u32, @intCast(@as(u10, @bitCast(data.imm0)))) | (@as(u32, @as(u16, @bitCast(data.imm1))) << 10),
            .JUk8 => |data| (@as(u32, data.rj.enc()) << 5) | (@as(u32, @as(u8, @bitCast(data.imm0))) << 10),
            .DJKA => |data| data.rd.enc() | (@as(u32, data.rj.enc()) << 5) | (@as(u32, data.rk.enc()) << 10) | (@as(u32, data.ra.enc()) << 15),
        };
    }
};

pub fn enc(self: Instruction) u32 {
    return self.opcode | self.data.enc();
}
